package rpc
import("encoding/json";"os";"path/filepath";"testing";"fmt";"github.com/postpilot/backend/internal/clip";"google.golang.org/protobuf/encoding/protojson")
func TestPrivateExportProofEditing(t *testing.T){root:=os.Getenv("POSTPILOT_PRIVATE_PROOF_ROOT");if root==""{t.Skip("explicit private proof only")};for _,n:=range []int{0,1}{b,e:=os.ReadFile(filepath.Join(root,fmt.Sprintf("proof-plan-%d.private.json",n)));if e!=nil{t.Fatal(e)};var p struct{Plan json.RawMessage;Analysis []clip.SourceAnalysis};if e=json.Unmarshal(b,&p);e!=nil{t.Fatal(e)};s,e:=clip.EditingStateFrom(clip.Project{EditPlan:string(p.Plan)},p.Analysis,clip.DefaultRenderConfig(clip.Environment{}));if e!=nil{t.Fatal(e)};out,e:=protojson.Marshal(editingProto(s));if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(root,fmt.Sprintf("proof-editing-%d.private.json",n)),out,0600);e!=nil{t.Fatal(e)}}}
